from pathlib import Path
import json,datetime
p=Path('guide/_waves/C10.screens.json');d=json.loads(p.read_text()); ss=d['screens']; by={s['name']:s for s in ss}
def click(name,role='button',**kw):return {'click':dict(role=role,name=name,exact=True,**kw)}
def wait(text):return {'waitFor':{'text':text},'timeout':300000}
def fill(label,value):return {'fill':{'label':label,'exact':True},'value':value}
def entry(name,shows,actions,expect,after=None):
 s=dict(name=name,shows=shows,actions=actions,expect=expect,height=1500)
 if after:s['after']=after
 return s
def add_before(target,s):
 if s['name'] in by:return
 ss.insert(next(i for i,v in enumerate(ss) if v['name']==target),s);by[s['name']]=s

def start(workspace,words,file=False,model=False):
 a=[{'goto':f'/apps/network/views/stops?workspaceKey={workspace}'},click('Workspace actions'),click('Change this model…' if model else 'Import…','menuitem')]
 if file:a +=[{'upload':{'css':'input[type=file]'},'value':'guide/samples/Haltestellen_Busbetrieb_Nord.xlsx'}]
 a +=[fill('What should change?' if model else 'Tell the assistant about this file (optional)',words),click('Ask the assistant' if model or not file else 'Read the workbook')]
 return a
by['use-assistant-stopped'].update(shows='Start one new workbook task in isolated C10 workbook pictures (fixture 1), then Stop while running. Wait up to 300000 ms for the genuine stopped state. Do not reuse failed job 67d62b49-304d-489c-9d35-87cd714446ed or photograph it as stopped. Run through use-assistant-reload together, same viewport/session; record task/job URLs before retakes.',actions=start('c10-workbook-pictures','Reuse the existing model where it fits. Read every sheet, check every row and propose the load. Wait for my acceptance before installing or loading anything.',file=True)+[{'waitFor':{'role':'button','name':'Stop','exact':True},'timeout':300000},click('Stop'),wait('You stopped the assistant')],expect=['You stopped the assistant','Nothing was installed or loaded','Tell the assistant how to go on','Go on as it was'])
by['use-assistant-proposal']['actions']=[click('Go on as it was'),wait('The assistant’s proposal'),wait('The check of every row')]
by['use-assistant-proposal']['shows']='Continue the same stopped task once. Wait for a checked proposal with actual row counts; no second upload. If it fails or asks questions, record the task address and resolve those questions in the same task before retaking. Run the entire six-picture chain together.'
for n in ['model-assistant-workbook-proposal','use-assistant-loaded','model-assistant-workbook-loaded','use-assistant-reload']:
 by[n]['shows']=by[n]['shows'].replace('confirmation of deletion is forbidden by the wave.','cancel this dialog because this picture needs only the warning.').replace('no activation.','retain the installed release without activating it.').replace('no activation','retain the installed release without activating it')
add_before('use-assistant-stopped',entry('c10-setup-assistant-ready','Fixture 1 prerequisite check: isolated workbook workspace with enabled working assistant; no mutation. This check deliberately precedes the new task. Keep all workbook-chain entries at 1440×1500.',[{'goto':'/apps/network/views/stops?workspaceKey=c10-workbook-pictures'},wait('Stops')],['Stops','C10 workbook pictures']))
words='Set the Abbreviation of the stop Chur Wiesental to C10-REVIEW. Reuse the existing model and record and change nothing else. Prepare a proposal for my review; do not load or publish yet.'
ss.append(entry('c10-setup-assistant-words','Start one words-only task in fixture 1 isolated C10 words pictures. Retain checked proposal, task and draft; never publish.',start('c10-words-pictures',words)+[wait('The assistant’s proposal')],['The assistant’s proposal','Accept the model']))
ss.append(entry('use-assistant-words','Same words-only proposal, before acceptance. Review that it changes only Chur Wiesental Abbreviation; actual provider text/counts require capture review.',[wait('The assistant’s proposal')],['The assistant’s proposal','Accept the model','Tell the assistant what to change']))
whole='Move every Stop record to a new type called Guide stop (plural Guide stops), keeping IDs, parents, all field values, relationships and history. Remove the old Stop type. Update every view, relationship rule, placement and consumer API reference to the new type; raise any changed consumer contract version. This is a whole-type move using a migration, not delete and recreate. Propose first.'
partial='Split all Stop records between two new types: Chur Wiesental becomes Review stop (plural Review stops); every other Stop becomes Other stop (plural Other stops). Keep IDs, parents, values, relationships and history. Remove Stop from the final model. This is a per-record partial move in a change set, not a whole-type migration or delete and recreate. Update affected views, placements, relationships and consumer APIs and raise changed consumer contract versions. Propose first.'
for suffix,workspace,words in [('whole-type-move','c10-whole-move-pictures',whole),('partial-move','c10-partial-move-pictures',partial)]:
 name='model-assistant-'+suffix
 ss.append(entry('c10-setup-assistant-'+suffix,'Fixture 1 workspace; start a model task, check the proposal then accept to prepare the move. Installs releases and, for partial moves, an unpublished change set. No Graubünden change. Provider outcomes must be reviewed before retakes.',start(workspace,words,model=True)+[wait('The assistant’s proposal'),click('Accept the model'),wait('Move the records to the new model' if suffix.startswith('whole') else 'Three steps are yours')],['Move the records to the new model','Preview the migration'] if suffix.startswith('whole') else ['Three steps are yours','Open the release']))
 if suffix.startswith('partial'):
  ss.append(entry('c10-setup-partial-activate','Activate only the bridge release in isolated C10 partial move pictures, then return to the SAME task with Alt+Left. First step becomes Done and second Next. Record task/release/change-set URLs. Requires proposal/result review: the release must hold both old and new shapes, with no blocking compatibility findings.',[click('Open the release'),click('Activate in a workspace…'),{'click':{'css':'[role="dialog"] .selection-trigger'}},click('C10 partial move pictures','option',exact=False) if False else {'click':{'role':'option','name':'C10 partial move pictures','exact':False}}, {'waitFor':{'css':'[role="dialog"] button.primary:enabled'}}, {'click':{'css':'[role="dialog"] button.primary:enabled'}},wait('Activated'),{'press':'Alt+ArrowLeft'},wait('Three steps are yours')],['Three steps are yours','Done','Next','Review the change set']))
 ss.append(entry(name,'Accepted move in its isolated picture workspace. '+('Shows whole-type counts and migration preview action before any migration.' if suffix.startswith('whole') else 'Shows three stages after bridge activation: first Done, review/publish Next. Do not publish or activate final release.'),[wait('Move the records to the new model' if suffix.startswith('whole') else 'Three steps are yours')],['Move the records to the new model','Preview the migration'] if suffix.startswith('whole') else ['Three steps are yours','Done','Next','Review the change set','3. Remove the emptied types']))
p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
with Path('guide/_waves/progress/C10-SCREENS-5.md').open('a') as f:f.write('\n'+datetime.datetime.now().astimezone().isoformat(timespec='minutes')+' — Finished assistant recipe unit in `C10.screens.json`: new stopped workbook task, same-task proposal/load/reload chain, words-only proposal, whole-type move and staged partial move. Added browser setup entries; isolated workspace prerequisites go in fixture item 1. No steering file; provider-generated results and bridge activation still need external capture review.\n')
